checkstyleInitScript:
import org.gradle.api.plugins.quality.Checkstyle

gradle.projectsEvaluated {
    def root = gradle.rootProject
    def paths = new File('/tmp/simplepoint-resource-owner-style-files.txt').readLines().collect { root.file(it) }
    def checks = []
    root.allprojects.each { p ->
        def sources = paths.findAll { it.toPath().startsWith(p.projectDir.toPath().resolve('src')) }
        if (!sources.isEmpty()) {
            checks.add(p.tasks.register('checkstyleResourceOwner', Checkstyle) {
                source sources
                classpath = p.sourceSets.test.compileClasspath
                configFile = root.file('checkstyle/google_checks.xml')
                maxWarnings = 0
                reports {
                    xml.required = true
                    html.required = true
                }
            })
        }
    }
    root.tasks.register('verifyResourceOwnerStyle') { dependsOn checks }
}

distribution.probeSource:
import java.util.List;
import java.util.Map;
import org.simplepoint.platform.composition.*;
import org.simplepoint.security.resource.ResourceDeclarationDocument;
import org.simplepoint.security.oauth2.resourceserver.scope.ClasspathResourceScopeRegistry;
import com.fasterxml.jackson.databind.ObjectMapper;

class VerifyResourceArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyResourceArtifacts.class.getClassLoader();
    var plan = ModuleCatalog.discover(loader).plan(List.of("workflow-http"));
    var owners = ModuleResourcePlan.owners(plan);
    if (!owners.equals(Map.of("workflow-http", "workflow"))) throw new AssertionError(owners);
    var document = ResourceDeclarationDocument.read("workflow-http", "workflow",
        ModuleResources.read("workflow-http", loader, "resources.json"));
    var scopes = new ClasspathResourceScopeRegistry(new ObjectMapper(), plan, loader);
    if (document.codes().isEmpty() || !document.codes().equals(scopes.snapshot().keySet())) {
      throw new AssertionError("Installed registration and scope declarations disagree");
    }
    var translations = org.simplepoint.plugin.i18n.api.initialization.I18nModuleInitializer.readDeclarations("workflow-http", loader);
    if (!translations.keySet().equals(java.util.Set.of("en-US", "zh-CN"))) throw new AssertionError("Missing locales");
    if (loader.getResource("META-INF/simplepoint/resources/workflow.json") != null) throw new AssertionError("Legacy resource copy remains");
    System.out.println("Installed artifact owners=" + owners + "; codes=" + document.codes().size()
        + "; locales=" + translations.keySet() + "; legacy copy absent");
  }
}
